import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("submitting a vendor with all documents extracted moves it to in_review", { tag: "@REV-01" }, async ({ apiAs }) => {
  // Arrange: a draft vendor with w9, insurance_certificate, and contract extracted
  const member = await apiAs("member");

  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev Check"), category: "services", contact_email: "rev-check@northwind-supply.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string; status: string };
  expect(vendor.status).toBe("draft");

  const uploads = [
    { kind: "w9", file: "w9.txt" },
    { kind: "insurance_certificate", file: "insurance_certificate.txt" },
    { kind: "contract", file: "contract.txt" },
  ] as const;

  const documentIds: string[] = [];
  for (const upload of uploads) {
    const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: upload.kind,
        file: { name: upload.file, mimeType: "text/plain", buffer: readFileSync(sample(upload.file)) },
      },
    });
    expect(res.status(), await res.text()).toBe(201);
    documentIds.push(((await res.json()) as { id: string }).id);
  }

  // Extraction runs in the background; wait until every document is extracted.
  for (const documentId of documentIds) {
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/documents/${documentId}`);
          expect(res.status(), await res.text()).toBe(200);
          return ((await res.json()) as { status: string }).status;
        },
        { timeout: 30_000, message: `document ${documentId} should be extracted` },
      )
      .toBe("extracted");
  }

  // Act
  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  expect(submit.status(), await submit.text()).toBe(200);
  const submitted = (await submit.json()) as { status: string; submitted_at: string | null };
  expect(submitted.status, await submit.text()).toBe("in_review");
  expect(submitted.submitted_at, await submit.text()).not.toBeNull();

  const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(audit.status(), await audit.text()).toBe(200);
  const { items } = (await audit.json()) as { items: { action: string }[] };
  expect(
    items.map((event) => event.action),
    await audit.text(),
  ).toContain("vendor.submitted");
});
